body.value:
(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
Sensor1_Fault := FALSE;
Sensor2_Fault := FALSE;
Sensor3_Fault := FALSE;
Alarm_Voting_Error := FALSE;
Healthy_Sensors_Count := 3;

FIT_101(
    PV_High := 180.0,
    PV_Low := 40.0,
    Scaling_Slope := 12.5,
    Scaling_Offset := -50.0,
    Alarm_Enable := TRUE);
PI_001(
    Alarm_Enable := TRUE);
FAL_101(
    DI_Raw := FIT_101.High_Alarm);
FAL_102(
    DI_Raw := FIT_101.Low_Alarm);
FAL_103(
    DI_Raw := FIT_101.General_Fault);
XV_106();
XV106NotOpen := NOT XV_106.FB_Opened;
XV106Interlock := XV106NotOpen OR XV_106.Alarm_Position_Error OR XV_106.Alarm_General;
IAL_101(
    Bool_In := XV106Interlock,
    Alarm_OnTrue := TRUE,
    Latch_Enable := TRUE);
FIC104Inhibit := IAL_101.Bool_Out OR FAL_103.DI_Out OR PI_001.High_Alarm OR PI_001.Low_Alarm;
FIC_104(
    PV := FIT_101.PV,
    SP := 100.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 1.5,
    TR := 0.6,
    TD := 0.1,
    Inhibit := FIC104Inhibit);
PV_103(
    Control_Signal := FIC_104.XOUT,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FAL_103.DI_Out);

(* Outputs published to other sections / HMI. *)
FIT101_Flow_PV_GPM := FIT_101.PV;
PI001_Pressure_PV_psig := PI_001.PV;
FIC104_MV_to_PV103_Pct := FIC_104.XOUT;

FIT_103(
    Scaling_Slope := 3.125,
    Scaling_Offset := -12.5,
    Alarm_Enable := TRUE);
LT_104(
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
LT104AutoInvert := NOT LT_104.General_Fault;
OverCapCompare := (FIT_103.PV > 60.0);
SPOverrideSelector := SEL(G := OverCapCompare, IN0 := 65.0, IN1 := 50.0);
LIC_101(
    AUTO := LT104AutoInvert,
    PV := LT_104.PV,
    SP := SPOverrideSelector,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 1.8,
    TR := 0.6,
    TD := 0.1,
    PV_High := 90.0,
    PV_Low := 15.0,
    Deviation_Limit := 5.0);
LevelAbove10Compare := (LT_104.PV > 10.0);
LevelLowInvert := NOT LevelAbove10Compare;
PV102InhibitLogic := LevelLowInvert OR LT_104.General_Fault;
PV_102(
    Control_Signal := LIC_101.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Timeout := T#10s,
    Inhibit := PV102InhibitLogic);

(* Outputs published to other sections / HMI. *)
FIT103_FlowRate := FIT_103.PV;
LT104_Level := LT_104.PV;
LIC101_PV102_ValveCommand := LIC_101.XOUT;
LAH101_Alarm := LIC_101.PV_High_Alarm;
LAL101_Alarm := LIC_101.PV_Low_Alarm;
LT104_FaultAlarm := LT_104.General_Fault;
OverCapacity_Active := OverCapCompare;
LevelAbove10_OK := LevelAbove10Compare;

LI_003(
    PV_Low := 10.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
TI_008(
    PV_High := 195.0,
    Scaling_Slope := 15.625,
    Scaling_Offset := -62.5,
    Alarm_Enable := TRUE);
LI3_Below15_GT := (15.0 > LI_003.PV);
XV104_Close_OR := LI_003.Low_Alarm OR LI3_Below15_GT;
XV104_AutoNot_NOT := NOT XV104_Close_OR;
LIC_103(
    AUTO := XV104_AutoNot_NOT,
    PV := LI_003.PV,
    SP := 70.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    KP := 2.5,
    TR := 0.8,
    TD := 0.1);
LIC_101_HI(
    Bool_In := LIC101_Condensate_High,
    Alarm_OnTrue := TRUE);
TI8_GT_200 := (TI_008.PV > 200.0);
InhibitFinal_OR := TI8_GT_200 OR LIC_101_HI.Bool_Out;
InhibitNot_NOT := NOT InhibitFinal_OR;
LI3_Above30_GT := (LI_003.PV > 30.0);
StartDelay_TON(
    IN := Column3_Start_CMD,
    PT := T#12s);
SteamStartPermissive_AND := StartDelay_TON.Q AND LI3_Above30_GT;
TIC106_Auto_AND := SteamStartPermissive_AND AND InhibitNot_NOT;
TIC_106(
    AUTO := TIC106_Auto_AND,
    PV := TI_008.PV,
    SP := 180.0,
    MV_MIN := 5.0,
    MV_MAX := 95.0,
    X0 := 0.0,
    KP := -3.2,
    TR := 1.0,
    TD := 0.3,
    Deviation_Limit := 10.0,
    Inhibit := InhibitFinal_OR);
XV_104(
    Control_Signal := LIC_103.XOUT,
    Manual_Mode := XV104_Close_OR,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Timeout := T#10s);
XV_105(
    Control_Signal := TIC_106.XOUT,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Timeout := T#10s,
    Inhibit := InhibitFinal_OR);
TIC106_DevTON(
    IN := TIC_106.Deviation_Alarm,
    PT := T#30s);

(* Outputs published to other sections / HMI. *)
TIC106_DeviationFault := TIC106_DevTON.Q;
TI_008_Temp_PV := TI_008.PV;
LI_003_Level_PV := LI_003.PV;
TIC_106_MV_Pct := TIC_106.XOUT;
LIC_103_MV_Pct := LIC_103.XOUT;
XV_105_Valve_Position_Pct := XV_105.Valve_Position;
XV_104_Valve_Position_Pct := XV_104.Valve_Position;

FIT_105(
    Scaling_Slope := 9.375,
    Scaling_Offset := -37.5,
    Alarm_Enable := TRUE);
LT_102(
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
LT_103(
    PV_High := 85.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
LT_107(
    PV_Low := 15.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
LT102_SignalFaults_A := LT_102.High_Alarm OR LT_102.Low_Alarm;
LT102_SignalFaults := LT102_SignalFaults_A OR LT_102.General_Fault;
LT103_Above90Check := (LT_103.PV > 90.0);
LIC106_ForceClose_A := LT103_Above90Check OR LT102_SignalFaults;
XV_101(
    Control_Signal := LIC_106.XOUT,
    Manual_Mode := LIC106_ForceClose,
    Manual_Position := 0.0,
    Timeout := T#10s,
    Inhibit := LIC106_ForceClose);
LIC106_ForceClose := LIC106_ForceClose_A OR XV_101.Alarm;
LIC106_ForceCloseClear := NOT LIC106_ForceClose;
LIC106_StartupDelay(
    IN := TRUE,
    PT := T#14s);
LIC106_AutoEnable := LIC106_StartupDelay.Q AND LIC106_ForceCloseClear;
LIC_106(
    AUTO := LIC106_AutoEnable,
    PV := LT_102.PV,
    SP := 65.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := -3.0,
    TR := 1.2,
    TD := 0.0,
    Inhibit := LIC106_ForceClose);
FIT105_HighLow := FIT_105.High_Alarm OR FIT_105.Low_Alarm;
FIT105_Invalid := FIT105_HighLow OR FIT_105.General_Fault;
FC8_SignalValid := NOT FIT105_Invalid;
FC8_StartupDelay(
    IN := TRUE,
    PT := T#14s);
FC8_AutoBase := FC8_StartupDelay.Q AND FC8_SignalValid;
LT107_Below20Check := (LT_107.PV < 20.0);
FC8_NoForceClose := NOT LT107_Below20Check;
FC8_AutoInterlocks := Decanter2_Online AND FC8_NoForceClose;
FC8_AutoEnable := FC8_AutoBase AND FC8_AutoInterlocks;
PV_104(
    Control_Signal := FC_008.XOUT,
    Manual_Mode := LT107_Below20Check,
    Manual_Position := 0.0,
    Inhibit := FC8_InhibitLogic);
FC8_ForceOpen := FIT_105.General_Fault OR PV_104.Alarm;
FC8_InhibitLogic := LT107_Below20Check OR FC8_ForceOpen;
FC_008(
    AUTO := FC8_AutoEnable,
    PV := FIT_105.PV,
    SP := 120.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 100.0,
    KP := 2.5,
    TR := 0.8,
    TD := 0.2,
    Deviation_Limit := 12.0,
    Inhibit := FC8_InhibitLogic);

(* Outputs published to other sections / HMI. *)
LT102_Level_PV_Pct := LT_102.PV;
FIT105_Flow_PV_LPM := FIT_105.PV;
LIC106_MV_To_XV101_Pct := LIC_106.XOUT;
FC008_MV_To_PV104_Pct := FC_008.XOUT;

TIT_101(
    PV_High := 55.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
FI_103(
    PV_Low := 5.0,
    Scaling_Slope := 6.25,
    Scaling_Offset := -25.0,
    Alarm_Enable := TRUE);
LC_002(
    Bool_In := LC002_LevelValid_In);
LC002NotActive_NOT := NOT LC_002.Bool_Out;
FIC103Inhibit_OR := TIT_101.General_Fault OR TIT_101.Low_Alarm OR LC002NotActive_NOT;
FIC_103(
    AUTO := TRUE,
    PV := TIT_101.PV,
    SP := 45.0,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 3.0,
    TR := 1.2,
    TD := 0.3,
    Inhibit := FIC103Inhibit_OR);
XV104Inhibit_OR := FI_103.Low_Alarm OR TIT_101.High_Alarm;
XV104OpenCmd_NOT := NOT XV104Inhibit_OR;
XV_104(
    Open_Cmd := XV104OpenCmd_NOT,
    Close_Cmd := XV104Inhibit_OR,
    Timeout := T#2s,
    Inhibit := XV104Inhibit_OR);
XV104NotOpen_NOT := NOT XV_104.FB_Opened;
LV102Inhibit_OR := XV104NotOpen_NOT OR FI_103.Low_Alarm OR TIT_101.General_Fault OR LC002NotActive_NOT OR TIT_101.High_Alarm OR XV_104.Alarm_General;
LV_102(
    Control_Signal := FIC_103.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Timeout := T#2s,
    Inhibit := LV102Inhibit_OR);

(* Outputs published to other sections / HMI. *)
TIT101_Temperature_PV_C := TIT_101.PV;
FI103_Flow_PV := FI_103.PV;
FIC103_Output_MV_Percent := FIC_103.XOUT;
LV102_ValvePositionCmd_Percent := LV_102.Valve_Position;
XV104_Open_FB := XV_104.FB_Opened;
LC002_ValidLevel := LC_002.Bool_Out;
